    }

    /**
     * 安全地解析并获取最终显示值。
     */
    function safeGetValue(value) {
        if (value === undefined || value === null) return '';
        let finalValue;
        if (Array.isArray(value)) {
            finalValue = String(value[0] !== undefined ? value[0] : '');
        } else if (typeof value === 'string' && value.includes('->')) {
            finalValue = value.split('->')[1].trim().split(' (')[0];
        } else {
            finalValue = String(value);
        }
        return stripQuotes(finalValue);
    }

    /**
     * 解析 "老值->新值" 字符串，返回数字数组。
     */
    function parseChangeValue(rawValue) {
        const value = (Array.isArray(rawValue)) ? String(rawValue[0]) : String(rawValue);
        if (typeof value !== 'string' || !value.includes('->')) return null;
        const parts = value.split('->');
        const oldValue = parseFloat(stripQuotes(parts[0]));
        const newValue = parseFloat(stripQuotes(parts[1]));
        return (!isNaN(oldValue) && !isNaN(newValue)) ? [oldValue, newValue] : null;
    }

    /**
     * 创建并添加升降箭头元素。
     */
    function addArrow(parent, values) {
         const [oldValue, newValue] = values;
        if (oldValue === newValue) return;
        const arrowSpan = document.createElement('span');
        arrowSpan.className = 'change-arrow';
        if (newValue > oldValue) {
            arrowSpan.innerHTML = ARROW_UP_SVG;
            arrowSpan.classList.add('up');
        } else {
            arrowSpan.innerHTML = ARROW_DOWN_SVG;
            arrowSpan.classList.add('down');
        }
        parent.insertBefore(arrowSpan, parent.firstChild);
    }

    /**
     * 更新纯文本或简单数值元素。
     */
    function updateTextElement(elementId, rawValue, isNumeric = false) {
        const element = document.getElementById(elementId);
        if (!element) return;
        const displayValue = safeGetValue(rawValue);
        element.textContent = displayValue;
        if (isNumeric) {
            const values = parseChangeValue(rawValue);
            if (values) {
                 addArrow(element, values);
            }
        }
    }

    /**
     * 更新心形进度条及旁边的数值/箭头。
     */
    function updateHeartRating(heartContainerId, valueContainerId, rawValue, color) {
        const finalDisplayValue = safeGetValue(rawValue);
        const finalValue = parseFloat(finalDisplayValue);
        const heartContainer = document.getElementById(heartContainerId);
        const valueContainer = document.getElementById(valueContainerId);
        if (!heartContainer || !valueContainer) return;

        if (isNaN(finalValue)) {
            heartContainer.innerHTML = '';
            valueContainer.innerHTML = 'N/A';
            return;
        }

        heartContainer.innerHTML = '';
        const displayValue = finalValue / 10;
        for (let i = 0; i < 10; i++) {
            const heart = document.createElement('div');
            heart.className = 'heart';
            const fillDiv = document.createElement('div');
            const percentage = Math.max(0, Math.min(1, displayValue - i)) * 100;
            fillDiv.style.background = `linear-gradient(to right, ${color} ${percentage}%, var(--heart-bg) ${percentage}%)`;
            heart.appendChild(fillDiv);
            heartContainer.appendChild(heart);
        }

        valueContainer.innerHTML = '';
        const valueSpan = document.createElement('span');
        valueSpan.textContent = finalValue.toString();
        const values = parseChangeValue(rawValue);
        if (values) {
             addArrow(valueContainer, values);
        }
        valueContainer.appendChild(valueSpan);
    }

    /**
     * 更新情绪双向进度条及下方的数值/箭头。
     */
    function updateEmotionDisplay(type, rawValue) {
        const finalDisplayValue = safeGetValue(rawValue);
        const finalValue = parseFloat(finalDisplayValue);
        const negBar = document.getElementById(`emotion-${type}-negative`);
        const posBar = document.getElementById(`emotion-${type}-positive`);
        const valueContainer = document.getElementById(`v-${type}-value`);
        if (!negBar || !posBar || !valueContainer) return;

        if (isNaN(finalValue)) {
            negBar.style.width = '0%';
            posBar.style.width = '0%';
            valueContainer.innerHTML = 'N/A';
            return;
        }

        const percentage = Math.abs(finalValue) * 50;
        negBar.style.width = (finalValue < 0) ? `${percentage}%` : '0%';
        posBar.style.width = (finalValue >= 0) ? `${percentage}%` : '0%';

        valueContainer.innerHTML = '';
        const valueSpan = document.createElement('span');
        valueSpan.textContent = finalValue.toFixed(2);
        const values = parseChangeValue(rawValue);
        if (values) {
             addArrow(valueContainer, values);
        }
        valueContainer.appendChild(valueSpan);
    }

    /**
     * 主更新函数：将数据填充到整个状态栏。
     */
    function updateDisplay(data) {
        if (!data) return;

        const baseViltia = mockGameData.stat_data.薇尔缇雅;

        updateTextElement('date', data.日期);
        updateTextElement('time', data.时间);

        const user = data.user || mockGameData.stat_data.user;
        updateTextElement('user-name', user.名字);
        updateTextElement('user-job', user.职业);
        updateTextElement('user-location', user.当前位置);
        updateTextElement('user-relation', user['与薇尔缇雅的关系']);

        const viltia = data.薇尔缇雅 || baseViltia;
        updateTextElement('v-location', viltia.当前位置);
        updateTextElement('v-outfit', viltia.着装);
        updateTextElement('v-thought', viltia.当前所想);

        updateHeartRating('v-affection-hearts', 'v-affection-value', viltia.好感度, 'var(--heart-pink)');
        updateHeartRating('v-promiscuity-hearts', 'v-promiscuity-value', viltia.淫乱值, 'var(--heart-purple)');

        const emotion = viltia.情绪状态 || baseViltia.情绪状态;
        updateEmotionDisplay('pleasure', emotion.pleasure);
        updateEmotionDisplay('arousal', emotion.arousal);

        const sexStatus = viltia.性经验状态 || baseViltia.性经验状态;
        updateTextElement('v-virgin', sexStatus.处女);
        updateTextElement('v-sex-total', sexStatus.总次数, true);
        updateTextElement('v-sex-oral-count', sexStatus.口交次数, true);
        updateTextElement('v-sex-oral-dev', sexStatus.口交开发, true);
        updateTextElement('v-sex-tits-count', sexStatus.乳交次数, true);
        updateTextElement('v-sex-tits-dev', sexStatus.乳房开发, true);
        updateTextElement('v-sex-pussy-count', sexStatus.穴交次数, true);
        updateTextElement('v-sex-pussy-dev', sexStatus.蜜穴开发, true);
        updateTextElement('v-sex-anal-count', sexStatus.菊交次数, true);
        updateTextElement('v-sex-anal-dev', sexStatus.后庭开发, true);
        updateTextElement('v-orgasm-count', sexStatus.高潮次数, true);
        updateTextElement('v-squirt-count', sexStatus.喷水次数, true);
    }

    /* 切换折叠区域 */
    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        content.classList.toggle('expanded');
        arrow.textContent = content.classList.contains('expanded') ? '▲' : '▼';
    }

    /**
     * 【已修正】初始化和数据加载函数
     */
    async function initDisplay() {
        let gameData;
        try {
            /* 尝试从真实环境中获取数据 */
            const message_data = await getChatMessages(getCurrentMessageId());
            gameData = message_data[0].data;
        } catch (e) {
            /* 如果失败（例如在本地测试），则使用模拟数据 */
            console.warn("无法从游戏中获取数据，将使用模拟数据进行测试。错误: ", e.message);
            gameData = mockGameData;
        }

        /* 优先使用 display_data，如果不存在，则使用 stat_data */
        const dataToUse = gameData.display_data || gameData.stat_data;
        if (dataToUse) {
            updateDisplay(dataToUse);
        } else {
            console.error("未能获取到任何有效数据（display_data 或 stat_data）");
        }
    }

    /* 页面启动 */
    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
</html>
